import { readFileSync, writeFileSync } from 'node:fs';

// Bundle the deploy's own template: rendering must not depend on an HTTP
// request re-entering the site's edge chain.
const template = readFileSync(new URL('../article.html', import.meta.url), 'utf8');
if (!template.includes('id="article-root"')) throw new Error('Article template has no article root');
writeFileSync(new URL('../netlify/shared/article-template.mjs', import.meta.url),
  '// Generated by scripts/bundle-article-template.mjs; edit article.html instead.\n' +
  'export default ' + JSON.stringify(template) + ';\n');
